begin;
truncate notification_push_deliveries,notifications cascade;
insert into work_calendar_entries(id,owner_id,work_date,title) values(tid(950),tid(1),current_date,'Own work'),(tid(951),tid(2),current_date,'Other work');
insert into web_push_subscriptions(id,user_id,endpoint,subscription) values(tid(952),tid(1),'https://fcm.googleapis.com/personal','{"endpoint":"https://fcm.googleapis.com/personal"}') on conflict do nothing;
select check_ok(not exists(select 1 from personal_reminders),'default off creates no schedules');
insert into notification_preferences(user_id) values(tid(1)) on conflict do nothing;
select check_ok((select not team_notifications and not calendar_reminders and not calendar_push from notification_preferences where user_id=tid(1)),'all legacy automatic defaults off');
update notification_preferences set team_notifications=true,team_push=true,calendar_reminders=true,calendar_push=true;
select check_ok(generate_notification_reminders_at(now(),null)=0,'old opt-ins never generate automatic reminders');
select check_ok(not has_table_privilege('authenticated','personal_reminders','update') and not has_table_privilege('authenticated','personal_reminders','insert'),'only canonical mutations');
select check_ok(not has_function_privilege('anon','save_personal_reminder(text,uuid,timestamptz,boolean,integer)','execute'),'anonymous denied');
select check_ok(not has_function_privilege('service_role','generate_notification_reminders_at(timestamptz,uuid[])','execute'),'client clock denied');
select set_config('request.jwt.claim.sub',tid(1)::text,true);set local role authenticated;
select check_ok(generate_work_calendar_notifications(current_date,1,1)=0,'legacy header generator cannot schedule reminders');
select check_ok(not exists(select 1 from personal_reminders),'legacy browser call does not create opt-in');
select check_ok(save_personal_reminder('calendar',tid(950))->>'status'='off','cancel unscheduled is no-op');
do $$begin begin perform save_personal_reminder(null,tid(950),now()+interval '1 hour');exception when invalid_parameter_value then return;end;raise exception 'null kind allowed';end$$;
do $$begin begin perform save_personal_reminder('calendar',tid(951),now()+interval '1 hour');exception when insufficient_privilege then return;end;raise exception 'another owner allowed';end$$;
do $$begin begin perform save_personal_reminder('surat',tid(17),now()+interval '1 hour');exception when insufficient_privilege then return;end;raise exception 'unrelated surat allowed';end$$;
do $$begin begin perform save_personal_reminder('calendar',tid(950),now()-interval '1 hour');exception when invalid_parameter_value then return;end;raise exception 'past accepted';end$$;
do $$begin begin perform save_personal_reminder('calendar',tid(950),'infinity');exception when invalid_parameter_value then return;end;raise exception 'infinite accepted';end$$;
select check_ok(save_personal_reminder('calendar',tid(950),now()+interval '1 hour')->>'status'='scheduled','explicit owner schedule');
select check_ok(save_personal_reminder('surat',tid(100),now()+interval '1 hour')->>'version'='1','visible surat schedule');
select check_ok((select count(*)=2 from personal_reminders),'only explicitly scheduled targets');
do $$begin begin perform save_personal_reminder('calendar',tid(950),now()+interval '2 hour');exception when serialization_failure then return;end;raise exception 'stale schedule accepted';end$$;
select check_ok(save_personal_reminder('calendar',tid(950),now()+interval '2 hour',false,1)->>'version'='2','reschedule increments version');
select set_config('request.jwt.claim.sub',tid(2)::text,true);
select check_ok(not exists(select 1 from personal_reminders),'RLS hides another owner');
reset role;
select check_ok(generate_notification_reminders_at(now()+interval '3 hour',array[tid(2)])=0,'restricted audience honored');
select check_ok(generate_notification_reminders_at(now()+interval '3 hour',array[tid(1)])=2,'due own reminders delivered once');
select check_ok(auth.uid()=tid(2),'scheduler restores caller JWT context');
select check_ok(generate_notification_reminders_at(now()+interval '3 hour',null)=0,'scheduler deduplicated');
select check_ok((select count(*)=2 from notifications where user_id=tid(1) and data->>'category'='personal_reminder'),'only owner recipient');
select check_ok(not exists(select 1 from notification_push_deliveries),'popup opt-out means in-app only');
select check_ok(exists(select 1 from notifications where link='/status-pengajuan?document='||tid(100)::text),'canonical surat deep link');
select check_ok(exists(select 1 from notifications where link like '/calendar?date=%&view=day&entry='||tid(950)::text),'calendar deep link');
select set_config('request.jwt.claim.sub',tid(1)::text,true);set local role authenticated;
select check_ok(save_personal_reminder('calendar',tid(950),now()+interval '1 hour',true,2)->>'version'='3','explicit popup schedule');
reset role;
select check_ok(generate_notification_reminders_at(now()+interval '2 hour',null)=1,'rescheduled reminder creates new notification');
select check_ok(exists(select 1 from notification_push_deliveries where status='pending'),'popup is queued with canonical receipt');
insert into notifications(id,user_id,title,is_read,data) values(tid(955),tid(2),'Forged',false,
 jsonb_build_object('category','personal_reminder','personal_reminder_id',(select id from personal_reminders where calendar_entry_id=tid(950)),'personal_reminder_version','3'));
select check_ok(not exists(select 1 from notification_push_deliveries where notification_id=tid(955)),'client JSON cannot grant popup authority');
select set_config('request.jwt.claim.sub',tid(1)::text,true);set local role authenticated;
select check_ok(save_personal_reminder('calendar',tid(950),null,false,3)->>'status'='cancelled','owner can disable');
reset role;
select check_ok(not exists(select 1 from claim_notification_push(20,null)),'cancelled popup not claimed');
select check_ok((select count(*)=3 from notifications where user_id=tid(1)),'reschedule/cancel preserves notification history');
-- A completed/inaccessible target must be stopped even if it was queued already.
select set_config('request.jwt.claim.sub',tid(1)::text,true);set local role authenticated;
select check_ok(save_personal_reminder('calendar',tid(950),now()+interval '1 hour',true,4)->>'status'='scheduled','reschedule after disable');
reset role;
select check_ok(generate_notification_reminders_at(now()+interval '2 hour',null)=1,'second popup queued');
update work_calendar_entries set status='completed' where id=tid(950);
select check_ok(not exists(select 1 from claim_notification_push(20,null)),'completed after generation suppresses popup');
update work_calendar_entries set status='planned' where id=tid(950);
select set_config('request.jwt.claim.sub',tid(1)::text,true);set local role authenticated;
select check_ok(save_personal_reminder('calendar',tid(950),now()+interval '1 hour',true,5)->>'status'='scheduled','new scheduled target');
select check_ok(save_personal_reminder('surat',tid(100),now()+interval '1 hour',true,1)->>'status'='scheduled','new surat schedule');
reset role;
update work_calendar_entries set status='completed' where id=tid(950);
update surat_registrasi set status='DONE' where id=tid(100);
select check_ok(generate_notification_reminders_at(now()+interval '2 hour',null)=0,'completed targets cancelled before generation');
select check_ok((select count(*)=2 from personal_reminders where status='cancelled'),'completed schedules retired');
insert into notifications(id,user_id,title,is_read,data) values(tid(956),tid(1),'Approval',false,'{"category":"approval"}'),(tid(957),tid(1),'Legacy',false,'{"category":"calendar_scheduled"}');
select check_ok(exists(select 1 from notification_push_deliveries where notification_id=tid(956)),'normal workflow notifications unchanged');
select check_ok(not exists(select 1 from notification_push_deliveries where notification_id=tid(957)),'retired auto categories suppressed');
insert into notifications(id,user_id,title,is_read,data) values(tid(958),tid(1),'Legacy header',false,'{"category":"deadline_overdue","dedupe_key":"work-calendar:deadline_overdue:fixture"}');
select check_ok(not exists(select 1 from notification_push_deliveries where notification_id=tid(958)),'legacy header automatic popup suppressed');
select check_ok(exists(select 1 from claim_notification_push(20,array[tid(1)]) where notification_id=tid(956)),'normal workflow delivery still claims');
select set_config('request.jwt.claim.sub',tid(2)::text,true);set local role authenticated;
select check_ok(save_personal_reminder('surat',tid(11),now()+interval '1 hour')->>'status'='scheduled','same department may schedule visible surat');
select check_ok(save_personal_reminder('calendar',tid(951),now()+interval '1 hour')->>'status'='scheduled','second owner may schedule own work');
reset role;
update profiles set department_id=tid(2) where id=tid(2);
select check_ok(generate_notification_reminders_at(now()+interval '2 hour',array[tid(2)])=1,'lost surat scope suppressed while own work remains visible');
select check_ok((select status='cancelled' from personal_reminders where user_id=tid(2) and surat_id=tid(11)),'lost access cancels schedule');
select set_config('request.jwt.claim.sub',tid(2)::text,true);set local role authenticated;
select check_ok(save_personal_reminder('calendar',tid(951),now()+interval '1 hour',true,1)->>'status'='scheduled','reschedule second owner');
reset role;update profiles set is_active=false where id=tid(2);
select check_ok(generate_notification_reminders_at(now()+interval '2 hour',array[tid(2)])=0,'inactive owner never notified');
select 'NTF08 personal reminders passed';
rollback;
